import java.util.*;

class Solution {
    public int countRoutes(int[][] grid) {
        int rows = grid.length, cols = grid[0].length;
        if (grid[0][0] == 1 || grid[rows - 1][cols - 1] == 1) return 0;
        int[] dp = new int[cols];      // dp[c] = routes to (current row, c)
        dp[0] = 1;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 1) dp[c] = 0;          // wall: no routes
                else if (c > 0) dp[c] += dp[c - 1];      // from above (old dp[c]) + from left
            }
        }
        return dp[cols - 1];
    }
}

