class Solution:
    def countRoutes(self, grid: List[List[int]]) -> int:
        cols = len(grid[0]); w = [0] * cols
        w[0] = 1
        for row in grid:
            for c in range(cols):
                if row[c] == 1: w[c] = 0
                elif c > 0: w[c] += w[c - 1]
        return w[-1]

