function countRoutes(grid) {
  const R_ = grid.length, C = grid[0].length;
  const w = Array.from({ length: R_ }, () => new Array(C).fill(0));
  for (let r = 0; r < R_; r++) for (let c = 0; c < C; c++) {
    if (grid[r][c] === 1) continue;
    if (r === 0 && c === 0) { w[r][c] = 1; continue; }
    w[r][c] = (r > 0 ? w[r - 1][c] : 0) + (c > 0 ? w[r][c - 1] : 0);
  }
  return w[R_ - 1][C - 1];
}
